import json,os,pathlib,signal,sys,time
mode=sys.argv[1]
def received(role,code):
 def handler(sig,frame):
  pathlib.Path(role+'.term').write_text(str(sig)+'\n')
  if mode!='hard':os._exit(code)
 return handler
signal.signal(signal.SIGTERM,received('parent',3))
signal.alarm(10)
grand=os.fork()
if grand==0:
 signal.signal(signal.SIGTERM,received('grand',5))
 signal.alarm(10)
 pathlib.Path('grand-ready').write_text('ready\n')
 while True:signal.pause()
deadline=time.monotonic()+2
while not pathlib.Path('grand-ready').exists():
 if time.monotonic()>deadline:raise RuntimeError('grandchild did not become ready')
 time.sleep(.01)
pathlib.Path('pids.json').write_text(json.dumps({'parent':os.getpid(),'grand':grand,'pgid':os.getpgrp(),'grand_pgid':os.getpgid(grand)}))
while True:signal.pause()

