import ctypes,json,os,pathlib,signal,subprocess,sys,time
lib=ctypes.CDLL(None,use_errno=True)
assert lib.prctl(36,1,0,0,0)==0,ctypes.get_errno()
mode=sys.argv[2]
opts={'default':'','foreground':'--foreground','hard':'-k 0.3'}[mode]
script='timeout '+opts+' 1.5 /usr/bin/python3 tree-child.py '+mode+'; printf "status=%s\n" "$?"'
side=subprocess.Popen([sys.argv[1],'--noprofile','--norc','-c',script],stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
info={};grand_status=None
try:
 out,err=side.communicate(timeout=8)
 assert side.returncode==0,side.returncode
 sys.stdout.buffer.write(out);sys.stdout.flush()
 sys.stderr.buffer.write(err);sys.stderr.flush()
 info=json.loads(pathlib.Path('pids.json').read_text())
 print('same-child-group='+str(int(info['pgid']==info['grand_pgid'])))
 print('separate-shell-group='+str(int(info['pgid']!=side.pid)))
 deadline=time.monotonic()+1
 while time.monotonic()<deadline:
  try:done,status=os.waitpid(info['grand'],os.WNOHANG)
  except ChildProcessError:done=0
  if done:grand_status=os.waitstatus_to_exitcode(status);break
  time.sleep(.01)
 print('parent-term='+str(int(pathlib.Path('parent.term').exists())))
 print('grand-term='+str(int(pathlib.Path('grand.term').exists())))
 print('grand-alive='+str(int(grand_status is None)))
 print('grand-status='+('running' if grand_status is None else str(grand_status)))
finally:
 if side.poll() is None:
  side.kill();side.wait()
 # The only targets are recorded descendants of this fixture's new session.
 if not info and pathlib.Path('pids.json').exists():info=json.loads(pathlib.Path('pids.json').read_text())
 for role in ('parent','grand'):
  if role in info:
   try:os.kill(info[role],signal.SIGKILL)
   except ProcessLookupError:pass
 deadline=time.monotonic()+2
 while True:
  try:done,status=os.waitpid(-1,os.WNOHANG)
  except ChildProcessError:break
  if not done:
   if time.monotonic()>deadline:raise RuntimeError('child cleanup timed out')
   time.sleep(.01)
 for name in ('pids.json','grand-ready'):pathlib.Path(name).unlink(missing_ok=True)

